{#- Sidra Construction Quotation print (CON-02, CON-03; decision G11). Sidra letterhead; English. -#}
<style>
	.sidra-quote { font-size: 11pt; }
	.sidra-quote h2 { margin-bottom: 4px; }
	.sidra-quote h3 { margin: 18px 0 6px; border-bottom: 1px solid #999; }
	.sidra-quote table { width: 100%; border-collapse: collapse; margin-bottom: 8px; }
	.sidra-quote th, .sidra-quote td { border: 1px solid #bbb; padding: 3px 6px; vertical-align: top; text-align: left; }
	.sidra-quote td.num, .sidra-quote th.num { text-align: right; }
	.sidra-quote .draft { color: #a00; font-weight: bold; }
	.sidra-quote .sign { height: 48px; }
</style>
<div class="sidra-quote">
	<div class="sidra-letterhead" style="text-align:center;margin-bottom:8px"><img src="{{ frappe.utils.get_url() }}/assets/sidra_realestate/images/sidra-logo.png" alt="Sidra Homes" style="height:60px"></div>
	<h2>Quotation {{ doc.name | e }}</h2>
	{% if doc.docstatus == 0 %}<p class="draft">Draft — not yet issued</p>{% endif %}
	{% if doc.docstatus == 2 %}<p class="draft">Cancelled</p>{% endif %}

	<table>
		<tr><th>From</th><td>{{ doc.company | e }}</td><th>Client</th><td>{{ frappe.db.get_value("Customer", doc.customer, "customer_name") | e }}</td></tr>
		<tr><th>Job</th><td>{{ doc.job | e }}</td><th>Valid until</th><td>{{ doc.get_formatted("valid_until") }}</td></tr>
	</table>

	<h3>Scope of work</h3>
	<p>{{ (doc.scope or "") | e }}</p>

	{% if doc.pricing_basis == "BOQ" %}
	<h3>Bill of quantities</h3>
	<table>
		<tr><th>Code</th><th>Description</th><th>Unit</th><th class="num">Quantity</th><th class="num">Rate</th><th class="num">Amount</th></tr>
		{% for row in doc.boq %}
		<tr><td>{{ (row.cost_code or "") | e }}</td><td>{{ row.description | e }}</td><td>{{ (row.uom or "") | e }}</td><td class="num">{{ row.get_formatted("qty") }}</td><td class="num">{{ row.get_formatted("rate", doc) }}</td><td class="num">{{ row.get_formatted("amount", doc) }}</td></tr>
		{% endfor %}
	</table>
	{% endif %}

	<table>
		<tr><th>{% if doc.pricing_basis == "BOQ" %}Total (from the bill of quantities){% else %}Fixed fee{% endif %}</th><td class="num"><strong>{{ doc.get_formatted("quoted_amount") }}</strong></td></tr>
	</table>

	<h3>Proposed terms</h3>
	<table>
		<tr><th>Start</th><td>{{ doc.get_formatted("start_date") }}</td><th>Duration</th><td>{{ doc.duration_days }} days (to {{ doc.get_formatted("end_date") }})</td></tr>
		<tr><th>Retention</th><td>{{ doc.get_formatted("retention_pct") or "0%" }}</td><th>Retention period</th><td>{{ doc.retention_period_months or 0 }} months</td></tr>
	</table>
	{%- set stages = frappe.get_all("Sidra Project Stage", filters={"parent": doc.job, "parenttype": "Sidra Construction Job", "billing_pct": [">", 0]}, fields=["stage_name", "billing_pct"], order_by="idx asc") -%}
	{% if stages %}
	<p>Payment milestones (share of the contract value, due on completion of each stage):</p>
	<table>
		<tr><th>Stage</th><th class="num">Share</th></tr>
		{% for s in stages %}<tr><td>{{ s.stage_name | e }}</td><td class="num">{{ frappe.format(s.billing_pct, {"fieldtype": "Percent"}) }}</td></tr>{% endfor %}
	</table>
	{% endif %}

	<h3>Acceptance</h3>
	<table>
		<tr><th>For the client (name, signature, date)</th><td class="sign"></td></tr>
		<tr><th>For {{ doc.company | e }}</th><td class="sign"></td></tr>
	</table>
</div>
